import { defineConfig } from 'vite';
import { rmSync } from 'node:fs';
import { resolve } from 'node:path';

// Built into ../app (served by GitHub Pages at /stock-retest-scanner/app/).
// ../app/data is generated by `python -m srs_app.export_data` and must survive builds,
// so emptyOutDir is off and only the old hashed assets are removed.
export default defineConfig({
  base: '/stock-retest-scanner/app/',
  build: { outDir: '../app', emptyOutDir: false, target: 'es2020', chunkSizeWarningLimit: 900 },
  plugins: [{
    name: 'clean-assets',
    buildStart() { rmSync(resolve(__dirname, '../app/assets'), { recursive: true, force: true }); },
  }],
});
